// Special events: a seasonal layer (background and effects) on top of any skin; colours and
// fonts stay the skin's. Load it in <head>, right after skin.js. Nothing is applied on load:
// the host calls restore() (its own choice, or the event in season), players follow the host
// (host.js → play.js). The events themselves live in site/events/ (see its README).
(function (G) {
  const KEY = 'meca-event';
  // events:registry:start (generated by tools/site/build_events.py from site/events/ — do not edit here)
  const ORDER = ["christmas"], EVENTS = {"christmas": {"name": {"en": "Christmas", "es": "Navidad", "fr": "Noël", "de": "Weihnachten", "it": "Natale", "nl": "Kerst", "pl": "Boże Narodzenie", "sk": "Vianoce"}, "icon": "/img/events/christmas/christmas-tree.svg", "dates": [{"from": "12-01", "to": "01-06"}], "effects": {"win": {"confetti": {"colors": ["#ffffff", "#d4f1ff", "#e63946", "#2a9d5c", "#f4c542"], "emoji": ["❄️", "🎄", "⭐"]}}}}, "test": {"name": {"en": "Test", "es": "Test", "fr": "Test", "de": "Test", "it": "Test", "nl": "Test", "pl": "Test", "sk": "Test"}, "icon": "/img/events/christmas/star.svg", "dates": [], "effects": {"win": {"confetti": {"colors": ["#ffd23f", "#2de2e6", "#ffffff"], "emoji": ["⭐"]}}}, "hidden": true}};
  // events:registry:end
  const root = document.documentElement;
  const valid = id => !!id && Object.prototype.hasOwnProperty.call(EVENTS, id);
  const mmdd = d => String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
  // inclusive ranges of "MM-DD"; a range with from > to wraps over New Year (12-01 → 01-06)
  function inDates(dates, date) {
    const k = mmdd(date);
    return (dates || []).some(r => r.from <= r.to ? k >= r.from && k <= r.to : k >= r.from || k <= r.to);
  }
  const suggested = (date = new Date()) => ORDER.find(id => inDates(EVENTS[id].dates, date)) || null;
  const name = (id, lang) => valid(id) ? EVENTS[id].name[lang] || EVENTS[id].name.en : '';
  const get = () => root.dataset.event || null;
  // save = false: show an event without changing this device's choice (players following the host)
  function set(id, save = true) {
    if (!valid(id)) id = null;
    if (id) root.dataset.event = id; else delete root.dataset.event;
    if (save) try { localStorage.setItem(KEY, JSON.stringify({ pick: id || 'none', sug: suggested() })); } catch (e) {}
    G.dispatchEvent(new CustomEvent('eventchange', { detail: id }));
    return id;
  }
  // the host's choice holds while the same event is in season; a new season starts from its suggestion
  function restore() {
    let s = null; try { s = JSON.parse(localStorage.getItem(KEY)); } catch (e) {}
    const sug = suggested();
    return set(s && s.sug === sug ? s.pick : sug, false);
  }
  // background slot (an event's layer.css shows it) and paused animations while the tab is hidden
  function slot() { if (!document.querySelector('.evbg')) document.body.insertAdjacentHTML('afterbegin', '<div class="evbg" aria-hidden="true"></div>'); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', slot); else slot();
  document.addEventListener('visibilitychange', () => root.classList.toggle('tab-hidden', document.hidden));

  G.Events = { list: ORDER, valid, name, inDates, suggested, effects: id => valid(id) ? EVENTS[id].effects : {}, icon: id => valid(id) ? EVENTS[id].icon : '', get, set, restore };
})(window);
